//! Authored/uncompiled/unrun. No process, server or model is launched.
use super::*;
fn configuration()->Configuration {Configuration {schema:"aniflow.amv-local-runtime/v1".into(),enabled:true,python_executable:"/synthetic/absent-python".into(),endpoint:"127.0.0.1:11434".parse().unwrap(),runtime_version:"0.12.3".into(),model_name:"synthetic:latest".into(),model_sha256:"a".repeat(64),service_egress_disabled_declared:true,context_tokens:4096,output_tokens:512,timeout_milliseconds:1000}}
fn request()->Request {Request {schema:"aniflow.amv-advisory-request/v1".into(),mode:Mode::EvidenceOnly,video_run_directory:"/synthetic/absent-video".into(),artifact_id:"delivery".into()}}
fn host()->HostResources {HostResources {cpu_threads:1,memory_mib:1,storage_mib:1,gpu_available:false,network_available:true}}
fn native(packet:&Packet,config:&Configuration)->NativeResult {NativeResult {schema:"aniflow.amv-ollama-result/v1".into(),candidate:Candidate {schema:"aniflow.amv-advisory-candidate/v1".into(),packet_sha256:packet.packet_sha256.clone(),declared_identity:config.identity().unwrap(),observed_fact_ids:vec!["video_frames".into()],suggestions:vec![],questions:vec![]},runtime_version_reported:config.runtime_version.clone(),model_name_reported:config.model_name.clone(),model_sha256_reported:config.model_sha256.clone(),model_calls:1,input_tokens:Some(100),output_tokens:Some(20)}}
#[test] fn disabled_reads_no_model_source_host_or_output(){let mut request=request();request.mode=Mode::Disabled;let mut config=configuration();config.endpoint="192.0.2.1:1".parse().unwrap();let value=run(&request,&config,Path::new("/synthetic/absent-output"),host(),&CancellationToken::new()).unwrap();assert_eq!(value.telemetry.state,State::Disabled);assert!(value.private_run_directory.is_none());}
#[test] fn unavailable_selected_provider_has_no_fallback_or_source_read(){let value=run(&request(),&configuration(),Path::new("/synthetic/absent-output"),host(),&CancellationToken::new()).unwrap();assert_eq!(value.telemetry.state,State::Unavailable);assert_eq!(value.telemetry.process_attempts,0);assert!(value.advisory.is_none()&&value.private_run_directory.is_none());}
#[test] fn remote_service_and_unbounded_settings_refuse(){let mut config=configuration();config.endpoint="192.0.2.1:11434".parse().unwrap();assert!(config.validate().is_err());config=configuration();config.output_tokens=config.context_tokens;assert!(config.validate().is_err());config=configuration();config.service_egress_disabled_declared=false;assert!(config.validate().is_err());}
#[test] fn semantic_identity_changes_for_model_and_settings(){let config=configuration();let identity=config.identity().unwrap();let mut changed=config.clone();changed.model_sha256="b".repeat(64);assert_ne!(identity.profile_sha256,changed.identity().unwrap().profile_sha256);changed=config.clone();changed.output_tokens+=1;assert_ne!(identity.profile_sha256,changed.identity().unwrap().profile_sha256);changed=config;changed.endpoint="[::1]:11434".parse().unwrap();assert_eq!(identity.profile_sha256,changed.identity().unwrap().profile_sha256);}
#[test] fn exact_provider_declarations_do_not_grant_offline_or_media_authority(){let registration=registration(&configuration()).unwrap();assert_eq!(registration.capability().id,CAPABILITY);assert_eq!(registration.capability().kind,crate::CapabilityKind::ArtifactValidator);assert!(!registration.capability().behavior.cacheable);assert!(registration.capability().behavior.side_effects.contains(&crate::SideEffect::Network));assert!(!registration.capability().behavior.side_effects.contains(&crate::SideEffect::Publish));}
#[test] fn changed_model_unknown_citation_and_usage_overrun_refuse(){let packet=crate::amv_advisory::tests::packet();let config=configuration();assert!(accept(&packet,&config,native(&packet,&config)).is_ok());let mut value=native(&packet,&config);value.model_sha256_reported="b".repeat(64);assert!(accept(&packet,&config,value).is_err());value=native(&packet,&config);value.candidate.observed_fact_ids.push("approved_visual_quality".into());assert!(accept(&packet,&config,value).is_err());value=native(&packet,&config);value.output_tokens=Some(513);assert!(accept(&packet,&config,value).is_err());}
#[test] fn portable_telemetry_omits_content_configuration_and_paths(){let value=result(State::Refused);let json=serde_json::to_string(&value.telemetry).unwrap();for excluded in ["endpoint","executable","prompt","retained_text","suggestions","/private/"]{assert!(!json.contains(excluded));}assert_eq!(value.telemetry.cost_state,"unknown");assert!(!value.telemetry.offline_qualified&&!value.telemetry.model_weights_verified);}
#[test] fn cancellation_before_resolution_does_not_create_workspace(){let token=CancellationToken::new();token.cancel();assert!(run(&request(),&configuration(),Path::new("/synthetic/absent-output"),host(),&token).is_err());}
